import org.junit.Test
import org.junit.Assert

class Tests {
    @Test
    fun testTribots() {
        Assert.assertEquals("stobirT", reverseString("Tribots"))
    }

    @Test
    fun testNumber() {
        Assert.assertEquals("5124", reverseString("4215"))
    }

    @Test
    fun testSingleChar() {
        Assert.assertEquals("A", reverseString("A"))
    }
}
